T = int(input())
for test in range(T):
	(n, d) = [int(v) for v in input().split()]
	A = [int(v) for v in input().split()]
	if d <= 0:
		if max(A) >= d:
			print(1)
		else:
			print(-1)
		continue
	tot = 0
	hist = [(0, 0)]
	best = float('inf')
	ind = -1
	for i in range(n):
		while hist and tot <= hist[-1][0]:
			hist.pop()
			if ind == len(hist):
				ind -= 1
		hist.append((tot, i))
		tot += A[i]
		while ind < len(hist) - 1 and hist[ind + 1][0] <= tot - d:
			ind += 1
		if ind > -1 and best > i - hist[ind][1] + 1:
			best = i - hist[ind][-1] + 1
	if best < float('inf'):
		print(best)
	else:
		print(-1)
